public int[] productExceptSelf(int[] nums){
    int n=nums.length; int[] res=new int[n]; Arrays.fill(res,1);
    int l=1;
    for(int i=0;i<n;i++){res[i]=l;l*=nums[i];}
    int r=1;
    for(int i=n-1;i>=0;i--){res[i]*=r;r*=nums[i];}
