public boolean isValidIP(String s){
    String[] parts=s.split("\\.");
    if(parts.length!=4) return false;
    for(String p:parts){
        if(p.isEmpty()||!p.matches("[0-9]+")) return false;
        if(p.charAt(0)=='0'&&p.length()>1) return false;
        if(Integer.parseInt(p)>255) return false;
