public ListNode addTwoNumbers(ListNode l1,ListNode l2){
    ListNode dummy=new ListNode(0),cur=dummy; int carry=0;
    while(l1!=null||l2!=null||carry!=0){
        int a=l1!=null?l1.val:0; int b=l2!=null?l2.val:0;
