Node clone(Node n,Map<Node,Node> visited){
    if(visited.containsKey(n)) return visited.get(n);
    Node copy=new Node(n.val);
    visited.put(n,copy);
    for(Node nb:n.neighbors) copy.neighbors.add(clone(nb,visited));
