def pacific_atlantic(heights):
    m,n=len(heights),len(heights[0])
    pac,atl=set(),set()
    def dfs(r,c,visited,prev):
        if (r,c) in visited or r<0 or r>=m or c<0 or c>=n or heights[r][c]<prev: return
        visited.add((r,c))
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            dfs(r+dr,c+dc,visited,heights[r][c])
    for r in range(m): dfs(r,0,pac,heights[r][0]); dfs(r,n-1,atl,heights[r][n-1])
    for c in range(n): dfs(0,c,pac,heights[0][c]); dfs(m-1,c,atl,heights[m-1][c])
    return [[r,c] for r in range(m) for c in range(n) if (r,c) in pac and (r,c) in atl]

