    for(int r=0;r<m;r++){dfs(heights,pac,r,0,0);dfs(heights,atl,r,n-1,0);}
    for(int c=0;c<n;c++){dfs(heights,pac,0,c,0);dfs(heights,atl,m-1,c,0);}
