class Trie:
    def __init__(self):
        self.children={}
        self.is_end=False
    def insert(self,word):
        node=self
        for c in word:
            if c not in node.children: node.children[c]=Trie()
            node=node.children[c]
        node.is_end=True
    def search(self,word):
        node=self
        for c in word:
            if c not in node.children: return False
            node=node.children[c]
